// Numbers are the brief's own (05 Section 4), not invented: 6 attempts on no-answer, 4 on busy,
// 8 on gatekeeper-only, hard-stop on opt-out, 4 waves total with 90-120 day gaps between waves.
const MAX_ATTEMPTS = { NoAnswer: 6, Busy: 4, GatekeeperOnly: 8 };
const MAX_WAVES = 4;
const RECYCLE_MIN_DAYS = 90;
const RECYCLE_MAX_DAYS = 120;

const input = $input.first().json.body;
const { disposition, attemptCountThisWave, wave, lastAttemptDate, repId } = input;

if (disposition === 'OptOut') {
  return [{ json: { action: 'STOP', hopperStatus: 'OptedOut', claimedByRepId: null, nextOwner: 'none', reason: 'Opt-out is a hard stop, no further attempts ever.' } }];
}

// Callback is its own top-level disposition (NOT a Connected- prefixed value) - see
// CRM-OBJECT-MODEL.md's Callback vs. Try-back distinction. Personal/rep-locked: stays out of the
// shared pool, only the rep who took the call sees it, until the promised time arrives.
if (disposition === 'Callback') {
  return [{
    json: {
      action: 'CALLBACK_SCHEDULED',
      hopperStatus: 'CallbackLocked',
      claimedByRepId: repId,
      nextOwner: 'rep',
      reason: 'Callback requested - locked to the rep who took the call until the promised time.',
    },
  }];
}

if (disposition && disposition.startsWith('Connected-')) {
  return [{ json: { action: 'STOP', hopperStatus: 'Completed', claimedByRepId: null, nextOwner: 'none', reason: 'Connected - this workflow only recycles no-contact dispositions.' } }];
}

const cap = MAX_ATTEMPTS[disposition];
if (cap === undefined) {
  return [{ json: { action: 'REVIEW', hopperStatus: null, claimedByRepId: repId, nextOwner: 'rep', reason: `Unrecognized disposition "${disposition}" - not in the attempt matrix, needs a human look rather than an automated guess. Left claimed by the calling rep rather than silently returned to the pool.` } }];
}

// Try-back (NoAnswer/Busy/GatekeeperOnly/VoicemailLeft, whichever is under its cap) - general
// behavior, not a distinct disposition value: goes straight back into the SHARED pool, not held for
// this rep. "tryback are placed back in campaign hopper, keep leads being worked."
if (attemptCountThisWave < cap) {
  return [{ json: { action: 'RETRY_NOW', hopperStatus: 'Available', claimedByRepId: null, nextOwner: 'pool', reason: `Attempt ${attemptCountThisWave + 1} of ${cap} for this wave.` } }];
}

if (wave >= MAX_WAVES) {
  return [{ json: { action: 'STOP', hopperStatus: 'Completed', claimedByRepId: null, nextOwner: 'none', reason: `Exhausted all ${MAX_WAVES} waves - no further recycling.` } }];
}

const nextEligibleDate = new Date(lastAttemptDate);
nextEligibleDate.setDate(nextEligibleDate.getDate() + RECYCLE_MIN_DAYS);
const windowEndDate = new Date(lastAttemptDate);
windowEndDate.setDate(windowEndDate.getDate() + RECYCLE_MAX_DAYS);

return [{
  json: {
    action: 'RECYCLE_NEXT_WAVE',
    hopperStatus: 'Available',
    claimedByRepId: null,
    nextOwner: 'pool',
    nextWave: wave + 1,
    eligibleFrom: nextEligibleDate.toISOString(),
    eligibleUntil: windowEndDate.toISOString(),
    reason: `Wave ${wave} exhausted at ${cap} attempts - recycles into wave ${wave + 1}, eligible ${RECYCLE_MIN_DAYS}-${RECYCLE_MAX_DAYS} days out, back in the shared pool (nextOwner: 'pool') once eligible.`,
  },
}];
